func TestPercentFamilyRequiresIncumbentSupportBeforeACrop(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var rows *port.Cells = port.NewCells()
	var plan *port.Cells = port.NewCells()
	var am *port.Cells = port.NewCells()
	var bm *port.Cells = port.NewCells()
	var pm *port.Cells = port.NewCells()
	pcttWords(text, words)
	port.AssertEq(emonT, oapct.PctRows(words, text, 0, 15, rows, am, bm, pm), 5, "five complete geometric rows")
	port.AssertEq(emonT, port.CellsAt(rows, 3), 1, "first identity closes on incumbents")
	port.AssertEq(emonT, port.CellsAt(rows, 19), 0, "the positive sign fails the negative change")
	port.AssertEq(emonT, oapct.PctPlan(words, rows, plan), 4, "one supported failing cell gets a crop")
	port.AssertEq(emonT, port.CellsAt(plan, 0), 14, "only the failing percent slot")
	port.AssertEq(emonT, port.CellsAt(plan, 2), 4, "four incumbent identities support the family")
	port.CellsSet(rows, 3, 0)
	port.AssertEq(emonT, oapct.PctPlan(words, rows, plan), 0, "three holds cannot authorize a crop")
}

func TestPercentCropCapHoldsTwoIndependentlySupportedFailingSlots(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var rows *port.Cells = port.NewCells()
	var proposal *port.Cells = port.NewCells()
	var am *port.Cells = port.NewCells()
	var bm *port.Cells = port.NewCells()
	var pm *port.Cells = port.NewCells()
	var w int32 = 15
	var x int32 = 0
	pcttWords(text, words)
	pcttWords(text, words)
	for w < 30 {
		x = evidence.OwGet(words, w, evidence.HdX0()) + 900
		evidence.OwSet(words, w, evidence.HdX0(), x)
		x = evidence.OwGet(words, w, evidence.HdX1()) + 900
		evidence.OwSet(words, w, evidence.HdX1(), x)
		w += 1
	}
	port.AssertEq(emonT, oapct.PctRows(words, text, 0, 30, rows, am, bm, pm), 10, "two complete five-row families")
	port.AssertEq(emonT, oapct.PctPlan(words, rows, proposal), 0, "two separately supported failures exceed this stage's one-crop cap")
	port.AssertEq(emonT, port.CellsLen(proposal), 0, "a cap veto leaves no stale proposal")
}

