func TestThreeTimesCropFilterPreservesFlatGrayAndCentralInk(emonT *testing.T) {
	var bms *port.BitmapSet = port.NewBitmapSet()
	var src *port.Bitmap = port.BmsPut(bms, 1, 9, 1, 1)
	var x int32 = 0
	for x < 9 {
		port.BitmapSetU8(src, x, 0, 0, 120)
		x += 1
	}
	oacrop.OaThree(bms, 2, 3, src)
	var flat *port.Bitmap = port.BmsGet(bms, 2)
	port.AssertEq(emonT, port.BitmapW(flat), 27, "integer x3 width")
	port.AssertEq(emonT, port.BitmapH(flat), 3, "integer x3 height")
	port.AssertEq(emonT, port.BitmapU8(flat, 13, 1, 0), 120, "normalized coefficients preserve flat gray")
	x = 0
	for x < 9 {
		port.BitmapSetU8(src, x, 0, 0, 255)
		x += 1
	}
	port.BitmapSetU8(src, 4, 0, 0, 0)
	oacrop.OaThree(bms, 4, 5, src)
	var ink *port.Bitmap = port.BmsGet(bms, 4)
	port.AssertEq(emonT, port.BitmapU8(ink, 13, 1, 0), 0, "source-center phase preserves black ink")
	port.AssertEq(emonT, port.BitmapU8(ink, 12, 1, 0), 47, "independent Lanczos sample left of the central stroke")
	port.AssertEq(emonT, port.BitmapU8(ink, 14, 1, 0), 47, "symmetric sample right of the central stroke")
}

